// Bible Atlas map pages (generated by scripts/generate-bible-atlas.mjs).
import atlasJson from "./atlas.json";

export type AtlasRef = [number] | [number, number];
export type AtlasMap = {
  slug: string;
  title: string;
  period: string;
  summary: string;
  notes: string;
  passage: AtlasRef;
  width: number;
  height: number;
  halfWidth: number;
  /** Content-hashed file names in /bible-data/atlas/. */
  files: { full: string; half: string; thumb: string; print: string };
  routes: { name: string; color: string; proposed: boolean; stops: { slug: string; label: string; ref: AtlasRef | null }[] }[];
  places: { slug: string; label: string }[];
  regions: string[];
};

export const atlasMaps = atlasJson as AtlasMap[];
export const atlasFile = (baseUrl: string, name: string) => `${baseUrl.endsWith("/") ? baseUrl.slice(0, -1) : baseUrl}/bible-data/atlas/${name}`;
